import {touchState,touchObject} from './kids-interaction.js';
import {labs,challenges,kidSources} from './kids-content.js';
import {readKids} from './kids-math.js';
import {playground,bindPlayground} from './kids-play.js';
const root=document.querySelector('#kids-app');let storage;try{storage=localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('unavailable');}};}
let data=readKids(storage),page='home',active='count',filter='all',round=null,storageFailed=false,teaching=false,lessonTab='play',shelf=0;const initial=new URLSearchParams(location.search);if(labs.some(l=>l.id===initial.get('lab'))){active=initial.get('lab');page='lab';teaching=initial.get('teach')==='1';}
const bi=(en,hi)=>data.locale==='hi'?hi:en,tx=o=>o[data.locale];
function save(){try{storage.setItem('aptitudelab-kids-v1',JSON.stringify(data));storageFailed=false;}catch{storageFailed=true;}}
function go(next,id){window.speechSynthesis?.cancel?.();if(page==='practice'&&round&&!round.done&&next!=='practice'&&!confirm(bi('Leave this practice round? Your answers in this round will not be saved.','अभ्यास छोड़ें? इस बार के उत्तर सुरक्षित नहीं होंगे।')))return;page=next;lessonTab='play';if(id)active=id;render();window.scrollTo(0,0);document.querySelector('#kids-main').focus({preventScroll:true});}
function render(){document.body.classList.toggle('teaching-view',teaching&&page==='lab');document.body.dataset.kidPage=page;document.documentElement.lang=data.locale;root.innerHTML=`<header class="kids-header"><a class="kids-brand" href="kids.html"><img src="icon.svg" alt=""><span>AptitudeLab <b>Kids</b></span></a><div><button class="kid-icon-button" id="kid-language" aria-label="${bi('Switch to Hindi','अंग्रेज़ी में बदलें')}">${bi('हिंदी','English')}</button><button class="kid-icon-button grownups" data-go="parents">${bi('For grown-ups','बड़ों के लिए')}</button></div></header><main id="kids-main" tabindex="-1">${page==='home'?home():page==='lab'?lesson():page==='practice'?practice():parents()}</main><nav class="kids-bottom" aria-label="${bi('Kids navigation','बच्चों का नेविगेशन')}"><button data-go="home" ${page==='home'?'aria-current="page"':''}><span>⌂</span>${bi('Playgrounds','खेलघर')}</button><button data-go="parents"><span>◈</span>${bi('My discoveries','मेरी सीख')}</button><a href="index.html"><span>▦</span>${bi('Exam Lab','परीक्षा लैब')}</a></nav><footer class="kids-footer">${bi('Small steps. Big discoveries. No timer needed.','छोटे कदम। बड़ी खोज। समय की कोई दौड़ नहीं।')}<button data-go="parents">${bi('Sources & progress','स्रोत और प्रगति')}</button></footer>${storageFailed?`<p role="status" class="storage-warning">${bi('Progress cannot be saved in this browser. You can still play.','इस ब्राउज़र में प्रगति सुरक्षित नहीं हो सकती। खेलना जारी रख सकते हैं।')}</p>`:''}`;
 root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelector('#kid-language').onclick=()=>{data.locale=data.locale==='en'?'hi':'en';window.speechSynthesis?.cancel?.();save();render();};
 root.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>go('lab',b.dataset.lab));root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;shelf=0;render();});
 document.querySelector('#listen')?.addEventListener('click',readAloud);document.querySelector('#start-practice')?.addEventListener('click',()=>{round={index:0,answers:{},checked:{},first:{},touched:{},done:false};page='practice';render();window.scrollTo(0,0);});
 document.querySelector('#teaching-view')?.addEventListener('click',()=>{teaching=!teaching;render();});root.querySelectorAll('[data-lesson-tab]').forEach(b=>b.onclick=()=>{lessonTab=b.dataset.lessonTab;render();});root.querySelectorAll('[data-shelf]').forEach(b=>b.onclick=()=>{shelf=+b.dataset.shelf;render();});if(page==='lab'&&(lessonTab==='play'||teaching))bindPlayground(active,bi);if(page==='practice')bindPractice();
 document.querySelector('#download-kids')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='aptitudelab-kids-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 document.querySelector('#clear-kids')?.addEventListener('click',()=>{if(confirm(bi('Clear the discoveries saved in this browser? Download them first if you want a copy.','इस ब्राउज़र की सीख मिटाएं? प्रति चाहिए तो पहले डाउनलोड करें।'))){data.results={};save();render();}});
}
function mascot(){return `<div class="number-buddies" aria-hidden="true"><div class="buddy buddy-two"><span>2</span><i></i><b></b></div><div class="buddy buddy-three"><span>3</span><i></i><b></b></div><div class="buddy buddy-one"><span>1</span><i></i><b></b></div><span class="buddy-spark">✦</span></div>`;}
function home(){const list=labs.filter(l=>filter==='all'||l.stage===filter),pages=Math.ceil(list.length/4);shelf=Math.min(shelf,pages-1);return `<section class="adventure-hello"><div><span class="kid-eyebrow">${bi('YOUR LITTLE MATHS WORLD','आपकी गणित की दुनिया')}</span><h1>${bi('Hello, explorer!','नमस्ते, खोजी!')}</h1><p>${bi('Touch. Discover. Try!','छुएं। खोजें। आजमाएं!')}</p></div><div class="mini-buddy" aria-hidden="true">★<span>◡</span></div></section><section class="adventure-shelf"><h2>${bi('Pick a little adventure','एक छोटा अभियान चुनें')}</h2><div class="kid-filters" role="group" aria-label="${bi('Learning stage','सीखने का चरण')}">${[['all',bi('All','सभी')],['start',bi('Start','शुरुआत')],['build',bi('Grow','आगे')],['stretch',bi('Tricks','विधियां')]].map(([id,label])=>`<button data-filter="${id}" class="${filter===id?'active':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div class="kid-lab-grid">${list.slice(shelf*4,shelf*4+4).map(l=>`<button class="kid-lab-card ${l.color}" data-lab="${l.id}"><span class="kid-lab-symbol">${l.icon}</span><h3>${tx(l.title)}</h3><p>${tx(l.desc)}</p><span class="kid-card-bottom">${data.results[l.id]?bi(`Explored · ${data.results[l.id].correct}/5`,`सीखा · ${data.results[l.id].correct}/5`):bi('Let’s explore','चलें खोजें')} <b>✦</b></span></button>`).join('')}</div><div class="shelf-pager"><button class="kid-icon-button" data-shelf="${shelf-1}" ${shelf===0?'disabled':''}>${bi('Back','पीछे')}</button><span aria-live="polite">${shelf+1} / ${pages}</span><button class="kid-icon-button" data-shelf="${shelf+1}" ${shelf===pages-1?'disabled':''}>${bi('More adventures','और अभियान')}</button></div></section>`;}
function lesson(){const l=labs.find(l=>l.id===active);return `<div class="lesson-top"><button class="kid-text" data-go="home">${bi('All adventures','सभी अभियान')}</button><button class="kid-icon-button" id="teaching-view" aria-pressed="${teaching}">${teaching?bi('Exit teaching view','शिक्षण दृश्य बंद करें'):bi('Teaching view','शिक्षण दृश्य')}</button><button class="kid-icon-button" id="listen">◖ ${bi('Listen','सुनें')}</button></div><div class="kid-lesson-heading"><span class="kid-lab-symbol ${l.color}">${l.icon}</span><h1>${tx(l.title)}</h1></div>${teaching?'':`<nav class="lesson-tabs" aria-label="${bi('Lesson steps','पाठ के चरण')}">${[['play',bi('✦ Play','✦ खेलें')],['why',bi('◉ Understand','◉ समझें')],['try',bi('★ Try','★ आजमाएं')]].map(([id,label])=>`<button data-lesson-tab="${id}" aria-current="${lessonTab===id?'step':'false'}">${label}</button>`).join('')}</nav>`}<section class="kid-panel lesson-stage">${lessonTab==='play'||teaching?`<div class="mission"><span>✦</span><p id="mission-text">${tx(l.mission)}</p></div><p id="speech-status" role="status" class="speech-status"></p><div id="playground">${playground(active,bi)}</div>`:lessonTab==='why'?`<div class="idea-mascot" aria-hidden="true">✦</div><h2>${bi('The little big idea','छोटा सा बड़ा विचार')}</h2><p class="idea-copy">${tx(l.idea)}</p><div class="talk-prompt">${bi('What changed? What stayed the same? Show someone with the objects.','क्या बदला? क्या वैसा रहा? वस्तुओं से किसी को दिखाएं।')}</div><button class="kid-button" data-lesson-tab="try">${bi('Let’s try it','चलें आजमाएं')}</button>`:`<div class="idea-mascot" aria-hidden="true">★</div><h2>${bi('Your turn, explorer!','अब आपकी बारी, खोजी!')}</h2><p class="idea-copy">${bi('Five little challenges. Touch, think and choose. You can try again and ask for a hint.','पांच छोटी चुनौतियां। छुएं, सोचें और चुनें। फिर कोशिश करें या संकेत लें।')}</p><button class="kid-button" id="start-practice">${bi('Start my challenges','मेरी चुनौतियां शुरू करें')}</button><p class="small-note">${bi('No timer. Take your time.','कोई टाइमर नहीं। अपनी गति से करें।')}</p>`}</section>`;}
function readAloud(){let status=document.querySelector('#speech-status');if(!status){lessonTab='play';render();status=document.querySelector('#speech-status');}if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){status.textContent=bi('Read-aloud is not available here. All instructions are shown as text.','यहां आवाज उपलब्ध नहीं है। सभी निर्देश लिखे हैं।');return;}const l=labs.find(l=>l.id===active);window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(tx(l.mission)+' '+tx(l.idea));utterance.lang=data.locale==='hi'?'hi-IN':'en-IN';utterance.rate=.82;utterance.onerror=()=>{status.textContent=bi('Voice playback is unavailable. You can read the instructions above.','आवाज नहीं चल सकी। ऊपर लिखे निर्देश पढ़ सकते हैं।');};window.speechSynthesis.speak(utterance);status.textContent=bi('Reading the instructions. Voice availability depends on your browser.','निर्देश पढ़े जा रहे हैं। आवाज की उपलब्धता ब्राउज़र पर निर्भर है।');}
function practice(){const qs=challenges[active],l=labs.find(l=>l.id===active);if(round.done){const correct=Object.values(round.first).filter(Boolean).length;return `<section class="kids-celebrate kid-panel"><div class="celebrate-star">✦</div><span class="kid-eyebrow">${bi('LOOK WHAT YOU DISCOVERED','देखें आपने क्या सीखा')}</span><h1>${bi('Your thinking is growing!','आपकी समझ बढ़ रही है!')}</h1><p>${bi(`You explored ${tx(l.title).toLowerCase()} and worked through all five challenges.`,`आपने ${tx(l.title)} सीखा और पांचों चुनौतियां पूरी कीं।`)}</p><div class="celebrate-score">${correct}<small>/ 5 ${bi('on the first try','पहले प्रयास में')}</small></div><p>${bi('Correcting an answer is learning too. You can explore and try again anytime.','उत्तर सुधारना भी सीखना है। कभी भी फिर खोजें और आजमाएं।')}</p><div class="play-actions"><button class="kid-button" data-go="home">${bi('Find another adventure','दूसरा अभियान खोजें')}</button><button class="kid-button light" data-lab="${active}">${bi('Play this one again','यह फिर खेलें')}</button></div></section>`;}const q=qs[round.index],checked=round.checked[q.id],picked=round.answers[q.id],touch=touchState(q.visual?.dots||0,round.touched[q.id]||[]);return `<div class="lesson-top"><button class="kid-text" data-go="lab">${bi('Back to playground','खेलघर में वापस')}</button><span>${round.index+1} / 5</span></div><section class="kid-panel kids-challenge"><span class="kid-eyebrow">${tx(l.title)}</span><div class="challenge-dots">${qs.map((_,i)=>`<i class="${i<=round.index?'done':''}"></i>`).join('')}</div><h1>${tx(q.prompt)}</h1>${q.visual?`<div class="touch-instruction" role="status">${touch.ready?bi('All counted! Now choose your answer.','सब गिन लिए! अब अपना उत्तर चुनें।'):bi('First, touch every star. Then choose your answer.','पहले हर तारे को छुएं। फिर अपना उत्तर चुनें।')}</div><div class="touch-stars" aria-label="${bi('Touch to count','छूकर गिनें')}">${Array.from({length:q.visual.dots},(_,i)=>`<button class="touch-star ${touch.touched.includes(i)?'counted':''}" data-touch-star="${i}" aria-label="${bi('Star','तारा')} ${i+1}" ${touch.touched.includes(i)?'disabled':''}>${touch.touched.includes(i)?touch.touched.indexOf(i)+1:'★'}</button>`).join('')}</div><p class="touch-progress" aria-live="polite">${bi(`${touch.count} stars touched`,`${touch.count} तारे छुए`)}</p>`:''}<div class="kid-answer-choices" ${!touch.ready?'hidden':''}>${q.choices.map((c,i)=>`<button class="kid-answer ${picked===i?'selected':''} ${checked&&picked===i?'answer-right':''}" data-kid-answer="${i}" aria-pressed="${picked===i}" ${checked?'disabled':''}>${tx(c)}</button>`).join('')}</div><div id="kid-answer-feedback" role="status">${checked?`<div class="kid-feedback good"><strong>${bi('You found it!','आपने खोज लिया!')}</strong><p>${tx(q.why)}</p></div>`:''}</div><div class="play-actions">${checked?`<button id="next-challenge" class="kid-button">${round.index===4?bi('Celebrate my discoveries','मेरी सीख का उत्सव'):bi('Next little challenge','अगली छोटी चुनौती')}</button>`:`<button id="check-kid-answer" class="kid-button" ${picked===undefined||!touch.ready?'disabled':''}>${bi('Check my idea','मेरा विचार जांचें')}</button><button id="kid-hint" class="kid-button light">${bi('Give me a hint','मुझे संकेत दें')}</button>`}</div><div id="kid-hint-text" class="hint-text"></div></section>`;}
function bindPractice(){if(round.done)return;const q=challenges[active][round.index];document.querySelectorAll('[data-touch-star]').forEach(b=>b.onclick=()=>{round.touched[q.id]=touchObject(q.visual.dots,round.touched[q.id]||[],+b.dataset.touchStar);render();const next=document.querySelector('[data-touch-star]:not(:disabled)')||document.querySelector('[data-kid-answer]');next?.focus({preventScroll:true});});document.querySelectorAll('[data-kid-answer]').forEach(b=>b.onclick=()=>{round.answers[q.id]=+b.dataset.kidAnswer;render();});document.querySelector('#kid-hint')?.addEventListener('click',()=>{document.querySelector('#kid-hint-text').textContent=touchState(q.visual?.dots||0,round.touched[q.id]||[]).ready?tx(q.why):bi('Touch a star and say one. Touch another and say the next number. Keep going until each star has a number.','एक तारा छूकर एक कहें। अगला छूकर अगली संख्या कहें। हर तारे पर अंक आने तक जारी रखें।');});document.querySelector('#check-kid-answer')?.addEventListener('click',()=>{if(!touchState(q.visual?.dots||0,round.touched[q.id]||[]).ready)return;const correct=round.answers[q.id]===q.answer;if(round.first[q.id]===undefined)round.first[q.id]=correct;if(correct){round.checked[q.id]=true;render();}else{document.querySelector('#kid-answer-feedback').innerHTML=`<div class="kid-feedback retry"><strong>${bi('Let’s try another idea.','दूसरा विचार आजमाएं।')}</strong><p>${tx(q.why)}</p></div>`;}});document.querySelector('#next-challenge')?.addEventListener('click',()=>{if(round.index<4)round.index++;else{round.done=true;data.results[active]={correct:Object.values(round.first).filter(Boolean).length,tried:5,at:Date.now()};save();}render();window.scrollTo(0,0);});}
function parents(){return `<div class="lesson-top"><button class="kid-text" data-go="home">${bi('All playgrounds','सभी खेलघर')}</button></div><section class="kid-panel parents"><span class="kid-eyebrow">${bi('FOR CURIOUS LEARNERS & THEIR GROWN-UPS','जिज्ञासु विद्यार्थियों और बड़ों के लिए')}</span><h1>${bi('A little guidance.<br>A lot of discovery.','थोड़ा मार्गदर्शन।<br>ढेर सारी खोज।')}</h1><p>${bi('Start with counting, comparing, addition and subtraction. Move to place value, equal groups and sharing when those ideas feel comfortable. Fractions, shapes, patterns and everyday maths can grow alongside them. Number tricks are an extension after the foundations.','गिनती, तुलना, जोड़ और घटाव से शुरू करें। समझ बनने पर स्थानमान, बराबर समूह और बंटवारे पर जाएं। भिन्न, आकार, पैटर्न और रोजमर्रा का गणित साथ बढ़ सकते हैं। संख्या विधियां बुनियाद के बाद हैं।')}</p><div class="teaching-steps"><span>◈ ${bi('Touch & explore','छुएं और खोजें')}</span><span>▧ ${bi('See a picture','चित्र देखें')}</span><span>123 ${bi('Connect the symbols','चिह्नों से जोड़ें')}</span></div><p>${bi('All 65 practice questions and visual activities are original. This is an introductory learning collection, not a complete grade syllabus or an NCERT-endorsed product. Vedic/base methods are explained through place value and distributive reasoning; no method replaces understanding.','सभी 65 अभ्यास प्रश्न और गतिविधियां मौलिक हैं। यह शुरुआती अध्ययन संग्रह है, संपूर्ण कक्षा पाठ्यक्रम या NCERT द्वारा अनुमोदित उत्पाद नहीं। वैदिक/आधार विधियां स्थानमान और वितरण के तर्क से समझाई हैं; कोई विधि समझ का विकल्प नहीं है।')}</p><h2>${bi('Your discoveries on this device','इस डिवाइस पर आपकी सीख')}</h2><div class="kids-progress-list">${labs.map(l=>`<button data-lab="${l.id}"><span>${tx(l.title)}</span><strong>${data.results[l.id]?`${data.results[l.id].correct}/5`:bi('Explore','खोजें')}</strong></button>`).join('')}</div><p class="small-note">${bi('Scores reflect the first checked answer in each completed round; corrections are encouraged. Latest round replaces the previous score. Progress stays in this browser. No child names, birthdays or accounts are requested.','अंक हर पूरी बार के पहले जांचे उत्तर पर आधारित हैं; सुधार को प्रोत्साहन है। आखिरी बार के अंक पहले के अंक बदलते हैं। प्रगति इसी ब्राउज़र में रहती है। बच्चे का नाम, जन्मतिथि या खाता नहीं मांगा जाता।')}</p><div class="play-actions"><button id="download-kids" class="kid-button light">${bi('Download progress','प्रगति डाउनलोड करें')}</button><button id="clear-kids" class="kid-text">${bi('Reset Kids Lab progress','Kids Lab की प्रगति मिटाएं')}</button></div><h2>${bi('Teaching references','शिक्षण के संदर्भ')}</h2><p class="small-note">${bi('Reviewed 24 November 2026. Official source access was partial; limitations are noted below.','समीक्षा 24 नवंबर 2026। आधिकारिक स्रोतों की उपलब्धता आंशिक थी; सीमाएं नीचे लिखी हैं।')}</p>${kidSources.map(s=>`<article class="kid-source"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name}</a><p>${tx(s.note)}</p></article>`).join('')}<p>${bi('Read-aloud uses voices available on your device/browser. Hindi voice availability varies. Instructions remain visible as text; there is no microphone recording.','पढ़कर सुनाने में डिवाइस/ब्राउज़र की आवाजें प्रयुक्त हैं। हिंदी आवाज की उपलब्धता अलग हो सकती है। निर्देश लिखे रहते हैं; माइक्रोफोन रिकॉर्डिंग नहीं होती।')}</p></section>`;}
render();
